CREATE TABLE "Customers" (
	"CustomerID" INTEGER GENERATED BY DEFAULT AS IDENTITY (INCREMENT BY 1 START WITH 1), 
	"Company Name" VARCHAR(50) NOT NULL, 
	"Active" BOOLEAN DEFAULT true NOT NULL, 
	"Notes" TEXT, 
	CONSTRAINT "Customers_pkey" PRIMARY KEY ("CustomerID")
)

CREATE UNIQUE INDEX "Customers_CompanyName" ON "Customers" ("Company Name")

CREATE TABLE "Order Lines" (
	"LineID" INTEGER GENERATED BY DEFAULT AS IDENTITY (INCREMENT BY 1 START WITH 1), 
	"OrderID" INTEGER NOT NULL, 
	"Product" VARCHAR(40) DEFAULT 'TBD', 
	"Quantity" SMALLINT DEFAULT 1 NOT NULL, 
	"Price" NUMERIC(19, 4), 
	"Discount" REAL DEFAULT 0, 
	CONSTRAINT "Order Lines_pkey" PRIMARY KEY ("LineID")
)

CREATE UNIQUE INDEX "Order Lines_OrderProduct" ON "Order Lines" ("OrderID", "Product")

CREATE TABLE "Orders" (
	"OrderID" INTEGER GENERATED BY DEFAULT AS IDENTITY (INCREMENT BY 1 START WITH 1), 
	"CustomerID" INTEGER NOT NULL, 
	"OrderDate" TIMESTAMP(0) WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	"Total" NUMERIC(19, 4) DEFAULT 0, 
	"Shipped" BOOLEAN DEFAULT false NOT NULL, 
	"Reference" VARCHAR(20), 
	CONSTRAINT "Orders_pkey" PRIMARY KEY ("OrderID")
)

ALTER TABLE "Orders" ADD CONSTRAINT "CustomersOrders" FOREIGN KEY("CustomerID") REFERENCES "Customers" ("CustomerID")

ALTER TABLE "Order Lines" ADD CONSTRAINT "OrdersOrderLines" FOREIGN KEY("OrderID") REFERENCES "Orders" ("OrderID") ON DELETE CASCADE
